    assert sent == [
        (1, {"a": 1, "x": 1, "y": 2}),
        (2, {"a": 1, "c": 3, "x": 1, "y": 2}),
    ]
    assert r["finalValue"] == {"a": 1, "c": 3, "x": 1, "y": 2}
